// 서버
res.writeHead(200, { 'Content-Type': 'text/event-stream', 'Cache-Control': 'no-cache', Connection: 'keep-alive' });
const t = setInterval(() => res.write(`data: ${JSON.stringify({ 진행: 진행률() })}\n\n`), 1000);
req.on('close', () => clearInterval(t));   // ← 안 지우면 유령 타이머가 쌓인다

// 클라이언트 — 재연결이 공짜다
const es = new EventSource('/progress');
es.onmessage = (e) => 그리기(JSON.parse(e.data));
